CREATE TABLE community_reaction (id BIGINT NOT NULL AUTO_INCREMENT,post_id BIGINT NOT NULL,user_id BIGINT NOT NULL,reaction_type VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_community_reaction UNIQUE(post_id,user_id,reaction_type),KEY idx_community_reaction_post(post_id,reaction_type),KEY idx_community_reaction_user(user_id),CONSTRAINT ck_community_reaction_type CHECK(reaction_type IN ('like','helpful','funny')),CONSTRAINT fk_community_reaction_post FOREIGN KEY(post_id) REFERENCES community_post(id) ON DELETE CASCADE,CONSTRAINT fk_community_reaction_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
